import{_ as c,r as t,o as r,c as u,e,a as n,s as o,d as a}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"开发主题 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"主题信息文件","slug":"主题信息文件","link":"#主题信息文件","children":[]},{"level":2,"title":"版本文件","slug":"版本文件","link":"#版本文件","children":[]},{"level":2,"title":"主题预览图片","slug":"主题预览图片","link":"#主题预览图片","children":[]},{"level":2,"title":"主题定制","slug":"主题定制","link":"#主题定制","children":[{"level":3,"title":"组合变量","slug":"组合变量","link":"#组合变量","children":[]}]},{"level":2,"title":"主题依赖","slug":"主题依赖","link":"#主题依赖","children":[]},{"level":2,"title":"多语言","slug":"多语言","link":"#多语言","children":[{"level":3,"title":"多语言文件结构","slug":"多语言文件结构","link":"#多语言文件结构","children":[]}]}],"relativePath":"2.x/zh-cn/themes/development.md","filePath":"2.x/zh-cn/themes/development.md"}'),i={name:"2.x/zh-cn/themes/development.md"};function d(g,s,k,m,h,v){const p=t("pre-heading"),l=t("post-heading");return r(),u("div",null,[e(p),s[0]||(s[0]=n("h1",null,"开发主题",-1)),e(l),s[1]||(s[1]=o(`<p>主题目录可以包括 <strong>theme.yaml</strong>、<strong>version.yaml</strong> 和 <strong>assets/images/theme-preview.png</strong> 文件。 这些文件对于本地开发是可选的，但对于在 October CMS 市场上发布的主题是必需的。</p><p><a id="oc-theme-information-file"></a></p><h2 id="主题信息文件"><a href="#主题信息文件" class="header-anchor">#</a> 主题信息文件</h2><p>主题信息文件 <strong>theme.yaml</strong> 包含主题描述、作者姓名、作者网站的 URL 以及其他一些信息。 该文件应放在主题根目录中：</p><div class="language- extra-class"><pre class="language-text"><code>themes/
  demo/
    theme.yaml    &lt;=== 主题信息文件
</code></pre></div><p><strong>theme.yaml</strong> 文件支持以下字段:</p><div class="table"><table tabindex="0"><thead><tr><th>领域</th><th>描述</th></tr></thead><tbody><tr><td><strong>name</strong></td><td>指定主题名称，必填。</td></tr><tr><td><strong>author</strong></td><td>指定作者姓名，必填。</td></tr><tr><td><strong>homepage</strong></td><td>指定作者网站 URL，必填。</td></tr><tr><td><strong>description</strong></td><td>主题描述，必填。</td></tr><tr><td><strong>previewImage</strong></td><td>自定义预览图片，相对于主题目录的路径，例如：<code>assets/images/preview.png</code>，可选。</td></tr><tr><td><strong>code</strong></td><td>主题代码，可选。 该值在 October CMS 市场上用于初始化主题代码值。</td></tr><tr><td><strong>authorCode</strong></td><td>主题作者代码，可选。 该值在 October CMS 市场上用于定义主题所有者。</td></tr><tr><td><strong>form</strong></td><td>配置数组或对表单域定义文件的引用，用于<a href="#oc-theme-customization">主题定制</a>，可选。</td></tr><tr><td><strong>require</strong></td><td>用于 <a href="#oc-theme-dependencies">主题依赖项</a> 的插件名称数组，可选。</td></tr></tbody></table></div><p>主题信息文件示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token key atrule">description</span><span class="token punctuation">:</span> <span class="token string">&quot;演示前端主题的基本概念&quot;</span>
<span class="token key atrule">author</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS&quot;</span>
<span class="token key atrule">homepage</span><span class="token punctuation">:</span> <span class="token string">&quot;https://octobercms.com&quot;</span>
<span class="token key atrule">code</span><span class="token punctuation">:</span> <span class="token string">&quot;Demo&quot;</span>
<span class="token key atrule">authorCode</span><span class="token punctuation">:</span> <span class="token string">&quot;武志伟&quot;</span>
</code></pre></div><p><a id="oc-version-file"></a></p><h2 id="版本文件"><a href="#版本文件" class="header-anchor">#</a> 版本文件</h2><p>主题版本文件 <strong>version.yaml</strong> 定义了当前的主题版本和变更日志。 该文件应放在主题根目录中：</p><div class="language- extra-class"><pre class="language-text"><code>themes/
  demo/
    ...
    version.yaml    &lt;=== 主题版本文件
</code></pre></div><p>文件格式如下：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">v1.0.1</span><span class="token punctuation">:</span> 主题初始化
<span class="token key atrule">v1.0.2</span><span class="token punctuation">:</span> 添加了更多功能
<span class="token key atrule">v1.0.3</span><span class="token punctuation">:</span> 删除了一些功能
</code></pre></div><h2 id="主题预览图片"><a href="#主题预览图片" class="header-anchor">#</a> 主题预览图片</h2><p>主题预览图像用于后端主题选择器。 图片文件<strong>theme-preview.png</strong> 应该放在主题的<strong>assets/images</strong> 目录下:</p><div class="language- extra-class"><pre class="language-text"><code>themes/
  demo/
    assets/
      images/
        theme-preview.png    &lt;=== 主题预览图
</code></pre></div><p>图像宽度应至少为 600 像素。 理想的纵横比是 1.5，例如 600x400px。</p><p><a id="oc-theme-customization"></a></p><h2 id="主题定制"><a href="#主题定制" class="header-anchor">#</a> 主题定制</h2><p>主题可以通过在主题信息文件中定义一个 <code>form</code> 键来支持配置值。 此键应包含配置数组或对表单字段定义文件的引用，有关更多信息，请参阅 <a href="./../backend/forms.html#oc-defining-form-fields">表单字段</a>。</p><p>以下是如何定义名为<strong>site_name</strong> 的网站名称配置字段的示例：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code>name<span class="token punctuation">:</span>我的主题
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> 站点名称
            <span class="token key atrule">comment</span><span class="token punctuation">:</span> 应出现在前端的网站名称
            <span class="token key atrule">default</span><span class="token punctuation">:</span> 我的超级网站！
</code></pre></div><blockquote><p><strong>注意</strong>：如果使用具有数组语法(<code>contact[name]</code>、<code>contact[email]</code> 等)的嵌套字段，您需要使用 下列的。</p></blockquote><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>ThemeData</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;contact&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>然后可以使用名为<code>this.theme</code>的<a href="./../markup/this-theme.html">默认页面变量</a> 在任何主题模板中访问该值。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>欢迎来到 <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> this<span class="token punctuation">.</span>theme<span class="token punctuation">.</span>site_name <span class="token delimiter punctuation">}}</span></span>!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>您还可以在单独的文件中定义配置，其中路径是相对于主题的。 以下定义将从主题内的文件 <strong>config/fields.yaml</strong> 中获取表单字段。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> 我的主题
<span class="token comment"># [...]</span>

<span class="token key atrule">form</span><span class="token punctuation">:</span> config/fields.yaml
</code></pre></div><p><strong>config/fields.yaml</strong>:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">site_name</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> 站点名称
        <span class="token key atrule">comment</span><span class="token punctuation">:</span> 应出现在前端的网站名称
        <span class="token key atrule">default</span><span class="token punctuation">:</span> 我的超级网站！
</code></pre></div><h3 id="组合变量"><a href="#组合变量" class="header-anchor">#</a> 组合变量</h3><p>使用 <code>|theme</code> <a href="./../markup/filter-theme.html">过滤器和组合器</a> 组合的资产可以将值传递给过滤器，例如 LESS 过滤器。 在定义表单字段时只需指定 <code>assetVar</code> 选项，该值应包含所需的变量名称。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">form</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>

        <span class="token key atrule">link_color</span><span class="token punctuation">:</span>
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Link color
            <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
            <span class="token key atrule">assetVar</span><span class="token punctuation">:</span> <span class="token string">&#39;link-color&#39;</span>
</code></pre></div><p>在上面的例子中，选择的颜色值将在 less 文件中作为 <code>@link-color</code> 可用。 假设我们有以下样式表参考：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>link</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>assets/less/theme.less<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token operator">|</span>theme <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">rel</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>stylesheet<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>使用 <strong>themes/yourtheme/assets/less/theme.less</strong> 中的一些示例内容：</p><div class="language-less extra-class"><pre class="language-less"><code><span class="token selector">a</span> <span class="token punctuation">{</span> <span class="token property">color</span><span class="token punctuation">:</span> <span class="token variable">@link-color</span> <span class="token punctuation">}</span>
</code></pre></div><p><a id="oc-theme-dependencies"></a></p><h2 id="主题依赖"><a href="#主题依赖" class="header-anchor">#</a> 主题依赖</h2><p>一个主题可以通过在<a href="#oc-theme-information-file">主题信息文件</a>中定义一个<strong>require</strong>选项来依赖插件，该选项应该提供一个被认为是需求的插件名称数组。 依赖于 <strong>Acme.Blog</strong> 和 <strong>Acme.User</strong> 的主题可以像这样定义这个需求：</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> <span class="token string">&quot;October CMS Demo&quot;</span>
<span class="token comment"># [...]</span>

<span class="token key atrule">require</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.User&quot;</span>
    <span class="token punctuation">-</span> <span class="token string">&quot;Acme.Blog&quot;</span>
</code></pre></div><p>首次安装主题时，系统会同时尝试安装所需的插件。</p><h2 id="多语言"><a href="#多语言" class="header-anchor">#</a> 多语言</h2><p>主题可以通过放置在主题目录的 <strong>lang</strong> 子目录中的文件提供后端多语言密钥。 这些多语言键只有在与 October 后端交互时才会自动注册，并且可以像 <a href="./../plugin/localization.html">插件多语言</a> 一样用于表单标签</p>`,46)),s[2]||(s[2]=n("blockquote",null,[n("p",null,[n("strong",null,"注意"),a("：翻译前端内容应使用 "),n("a",{href:"https://octobercms.com/plugin/rainlab-translate",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("RainLab.Translate"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),n("span",{class:"sr-only"},"(opens new window)")])]),a(" 插件处理。")])],-1)),s[3]||(s[3]=o(`<h3 id="多语言文件结构"><a href="#多语言文件结构" class="header-anchor">#</a> 多语言文件结构</h3><p>以下是主题的 lang 目录示例：</p><div class="language- extra-class"><pre class="language-text"><code>themes/
  acme/           &lt;=== 主题目录
    lang/         &lt;=== 多语言目录
      en/         &lt;=== 语言目录
        lang.php  &lt;=== 多语言文件
      fr/
        lang.php
</code></pre></div><p><strong>lang.php</strong> 文件应该定义并返回一个任意深度的数组，例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;options&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;website_name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span>
    <span class="token punctuation">]</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>然后你就可以使用<code>theme.theme-code::lang.key</code> 来引用这些键。 在上面的例子中，你用来引用<code>website_name</code>多语言的完整语言键是<code>theme.acme::lang.options.website_name</code>。</p>`,6))])}const _=c(i,[["render",d]]);export{f as __pageData,_ as default};
